<template> <ion-page> <ion-header> <ion-toolbar> <ion-buttons slot="start"> <ion-back-button default-href="/settings"></ion-back-button> </ion-buttons> <ion-title>Notifications</ion-title> </ion-toolbar> </ion-header> <ion-content :fullscreen="true"> <ion-list> <ion-item> <ion-label>Transaction Alerts</ion-label> <ion-toggle v-model="notifications.transactionAlerts" @ionChange="updateNotifications"></ion-toggle> </ion-item> <ion-item> <ion-label>Staking Updates</ion-label> <ion-toggle v-model="notifications.stakingUpdates" @ionChange="updateNotifications"></ion-toggle> </ion-item> <ion-item> <ion-label>System Announcements</ion-label> <ion-toggle v-model="notifications.systemAnnouncements" @ionChange="updateNotifications"></ion-toggle> </ion-item> <ion-item> <ion-label position="stacked">Balance Threshold</ion-label> <ion-input v-model.number="notifications.balanceThreshold" type="number" placeholder="Enter threshold"></ion-input> </ion-item> </ion-list> <ion-button expand="block" @click="updateNotifications" :disabled="loading">Save Changes</ion-button> <ion-toast :is-open="toast.isOpen" :message="toast.message" :duration="2000" @didDismiss="toast.isOpen = false" ></ion-toast> </ion-content> </ion-page> </template> <script lang="ts"> import { defineComponent, ref, onMounted } from 'vue'; import { IonPage, IonHeader, IonToolbar, IonButtons, IonBackButton, IonTitle, IonContent, IonList, IonItem, IonLabel, IonToggle, IonInput, IonButton, IonToast, } from '@ionic/vue'; import api from '../services/api'; import { NotificationSettings } from '../types/settings'; export default defineComponent({ name: 'NotificationSettings', components: { IonPage, IonHeader, IonToolbar, IonButtons, IonBackButton, IonTitle, IonContent, IonList, IonItem, IonLabel, IonToggle, IonInput, IonButton, IonToast }, setup() { const notifications = ref<NotificationSettings>({ transactionAlerts: false, stakingUpdates: false, systemAnnouncements: false, balanceThreshold: 0, }); const loading = ref(false); const toast = ref({ isOpen: false, message: '' }); const fetchNotifications = async () => { try { const response = await api.get('/user/notifications'); notifications.value = response.data; } catch (error) { toast.value = { isOpen: true, message: 'Failed to load notification settings' }; } }; const updateNotifications = async () => { loading.value = true; try { await api.post('/user/notifications', notifications.value); toast.value = { isOpen: true, message: 'Notification settings updated' }; } catch (error) { toast.value = { isOpen: true, message: 'Failed to update notification settings' }; } finally { loading.value = false; } }; onMounted(fetchNotifications); return { notifications, loading, toast, updateNotifications }; }, }); </script>